import re
path='/app/text.gcode'
with open(path) as f:
    lines=f.readlines()
# parse extrusions in final segment (15014-98473) : collect (x,y,z)
import re
pat=re.compile(r'([XYZE])(-?[0-9.]+)')
pos={'X':0,'Y':0,'Z':0}
cur=None
pts=[] # for final seg only
for i,line in enumerate(lines, start=1):
    s=line.strip()
    if s.startswith('M486'):
        m=re.search(r'M486\s+S(-?\d+)',s)
        if m:
            cur=int(m.group(1)) if int(m.group(1))!=-1 else None
        continue
    if i<15014 or i>98473:
        # still need to track pos? not needed
        if s.startswith('G0') or s.startswith('G1'):
            for k,v in pat.findall(s):
                pos[k]=float(v)
        continue
    if s.startswith('G0') or s.startswith('G1'):
        # update
        hasXY=('X' in s or 'Y' in s)
        for k,v in pat.findall(s):
            pos[k]=float(v)
        if 'E' in s and hasXY:
            me=re.search(r'E(-?[0-9.]+)',s)
            if me and float(me.group(1))>0:
                pts.append((pos['X'],pos['Y'],pos['Z']))
print(len(pts))
# stats by Z bands
from collections import Counter
import math
zs=sorted(set(round(z,2) for x,y,z in pts))
print(zs[:20], zs[-20:])
# also X/Y ranges per Z band low vs high
for z in [3.0,3.2,5,10,20,30,40,50,60,64]:
    band=[(x,y) for x,y,zz in pts if abs(zz-z)<0.2]
    if band:
        xs=[x for x,y in band]; ys=[y for x,y in band]
        print(f"Z~{z}: n={len(band)} X[{min(xs):.1f}-{max(xs):.1f}] Y[{min(ys):.1f}-{max(ys):.1f}]")
